+import { describe, expect, test } from "bun:test";
+import { render } from "../src/engine";
+
+describe("render", () => {
+  test("renders escaped, raw, missing, and comment values", () => {
+    expect(render("{{! no }}{{value}}|{{{value}}}|{{missing}}", { value: `&<>"'` }))
+      .toBe("&amp;&lt;&gt;&quot;&#39;|&<>\"'|");
+  });
+
+  test("preserves whitespace and resolves nested paths", () => {
+    expect(render(" a\n  {{user.name}}  \n", { user: { name: "Ada" } }))
+      .toBe(" a\n  Ada  \n");
+  });
+
+  test("uses the specified truthiness rules", () => {
+    for (const value of ["", 0, false, null, undefined, []]) {
+      expect(render("{{#if value}}yes{{else}}no{{/if}}", { value })).toBe("no");
+    }
+    for (const value of ["x", 1, true, {}, [0]]) {
+      expect(render("{{#if value}}yes{{else}}no{{/if}}", { value })).toBe("yes");
+    }
+  });
+
+  test("supports nested conditionals", () => {
+    const template = "{{#if a}}A{{#if b}}B{{else}}C{{/if}}{{else}}D{{/if}}";
+    expect(render(template, { a: true, b: false })).toBe("AC");
+    expect(render(template, { a: false, b: true })).toBe("D");
+  });
+
+  test("iterates arrays with item, index, root fallback, and else", () => {
+    const template = "{{#each users}}[{{@index}}:{{this.name}}/{{title}}]{{else}}empty{{/each}}";
+    expect(render(template, { title: "Team", users: [{ name: "A" }, { name: "B" }] }))
+      .toBe("[0:A/Team][1:B/Team]");
+    expect(render(template, { title: "Team", users: [] })).toBe("empty");
+    expect(render(template, { title: "Team", users: "not an array" })).toBe("empty");
+  });
+
