+type Node =
+  | { type: "text"; value: string }
+  | { type: "value"; path: string; escaped: boolean; location: Location }
+  | {
+      type: "if";
+      path: string;
+      body: Node[];
+      alternate: Node[];
+      location: Location;
+    }
+  | {
+      type: "each";
+      path: string;
+      body: Node[];
+      alternate: Node[];
+      location: Location;
+    };
