+    ? (value as Record<string, unknown>)[key]
+    : undefined;
+}
+
+function descend(value: unknown, path: string): unknown {
+  if (!path) return value;
+  return path.split(".").reduce(property, value);
+}
+
+function resolve(path: string, context: RenderContext): unknown {
+  if (path === "this") return context.hasItem ? context.item : context.root;
+  if (path.startsWith("this.")) {
+    return descend(context.hasItem ? context.item : context.root, path.slice(5));
+  }
+  if (path === "@index") return context.hasItem ? context.index : undefined;
+  return descend(context.root, path);
+}
+
+function isTruthy(value: unknown): boolean {
+  if (Array.isArray(value)) return value.length > 0;
+  return Boolean(value);
+}
+
+function scalar(value: unknown, path: string, location: Location): string {
+  if (value === undefined || value === null) return "";
+  if (
+    typeof value === "string" ||
+    typeof value === "number" ||
+    typeof value === "bigint" ||
+    typeof value === "boolean"
+  ) {
+    return String(value);
+  }
+  throw new Error(
+    `Cannot render non-scalar value at "${path}" (line ${location.line}, column ${location.column})`,
+  );
+}
