+function renderNodes(nodes: Node[], context: RenderContext): string {
+  let output = "";
+  for (const node of nodes) {
+    if (node.type === "text") {
+      output += node.value;
+    } else if (node.type === "value") {
+      const value = scalar(resolve(node.path, context), node.path, node.location);
+      output += node.escaped ? escapeHtml(value) : value;
+    } else if (node.type === "if") {
+      const branch = isTruthy(resolve(node.path, context)) ? node.body : node.alternate;
+      output += renderNodes(branch, context);
+    } else {
+      const value = resolve(node.path, context);
